solution.python:
def two_sum(nums: list[int], target: int) -> list[int]:
    seen = {}  # Value -> earlier index.
    for i, value in enumerate(nums):
        complement = target - value
        # Check before storing to avoid using this element twice.
        if complement in seen:
            return [seen[complement], i]
        seen[value] = i
    raise ValueError("No valid pair")

solution.java:
import java.util.HashMap;
import java.util.Map;

class Solution {
    public int[] twoSum(int[] nums, int target) {
        Map<Long, Integer> seen = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            // Use long arithmetic to avoid int overflow.
            long complement = (long) target - nums[i];
            Integer earlier = seen.get(complement);
            // Look up before storing: indices must be distinct.
            if (earlier != null) {
                return new int[] {earlier, i};
            }
            seen.put((long) nums[i], i);
        }
        throw new IllegalArgumentException("No valid pair");
    }
}

solution.javascript:
function twoSum(nums, target) {
    const seen = new Map(); // Value -> earlier index.
    for (let i = 0; i < nums.length; i++) {
        const complement = target - nums[i];
        // Check before storing to avoid reusing the current element.
        if (seen.has(complement)) {
            return [seen.get(complement), i];
        }
        seen.set(nums[i], i);
    }
    throw new Error("No valid pair");
}
